changeSet.sql:
DO $$
DECLARE
    r          RECORD;
    sf_id      BIGINT;
    metric     BIGINT;
    next_order INT;
BEGIN
    SELECT COALESCE(MAX(order_number), 0) INTO next_order FROM stop_factors.stop_factor WHERE valid_to IS NULL;

    FOR r IN
        SELECT * FROM (VALUES
            -- name, calculator, params, UNDERWRITER above, REJECTED above, products
            ('[Тест] Открытые кредиты: Ипотека и Автокредит', 'OPEN_CREDITS_COUNT', '{}', 2, 4, ARRAY[2, 3]::bigint[]),
            ('[Тест] Запросы в кредитное бюро за 7 дней: Микрокредит', 'BUREAU_REQUESTS_COUNT', '{"days": 7}', 2, NULL::int, ARRAY[4]::bigint[])
        ) AS t(name, calculator, params, underwriter_above, rejected_above, products)
    LOOP
        SELECT id INTO metric FROM stop_factors.stop_factor_metric WHERE calculator = r.calculator ORDER BY id LIMIT 1;
        IF metric IS NULL THEN
            RAISE EXCEPTION 'Metric % not found', r.calculator;
        END IF;

        sf_id := nextval('stop_factors.stop_factor_id_generator');
        next_order := next_order + 1;
        INSERT INTO stop_factors.stop_factor (id, created_date, name, description, is_active, order_number,
                                              version_number, valid_from, change_reason, created_by, metric_id, params)
        VALUES (sf_id, now(), r.name, 'Тестовые данные changelog 1.5, только для локальной базы', true, next_order,
                1, now(), 'Тестовые данные', 'migration', metric, r.params::jsonb);

        IF r.rejected_above IS NOT NULL THEN
            INSERT INTO stop_factors.stop_factor_condition (id, created_date, stop_factor_id, value, value_type, result)
            VALUES (nextval('stop_factors.stop_factor_condition_id_generator'), now(), sf_id, r.rejected_above::text, 'INTEGER', 'REJECTED');
        END IF;
        INSERT INTO stop_factors.stop_factor_condition (id, created_date, stop_factor_id, value, value_type, result)
        VALUES (nextval('stop_factors.stop_factor_condition_id_generator'), now(), sf_id, r.underwriter_above::text, 'INTEGER', 'UNDERWRITER');

        INSERT INTO stop_factors.stop_factor_product (stop_factor_id, product_id)
        SELECT sf_id, unnest(r.products);
    END LOOP;
END $$;

rollback.sql:
DELETE FROM stop_factors.stop_factor_product
WHERE stop_factor_id IN (SELECT id FROM stop_factors.stop_factor WHERE change_reason = 'Тестовые данные' AND created_by = 'migration');
DELETE FROM stop_factors.stop_factor_condition
WHERE stop_factor_id IN (SELECT id FROM stop_factors.stop_factor WHERE change_reason = 'Тестовые данные' AND created_by = 'migration');
DELETE FROM stop_factors.stop_factor WHERE change_reason = 'Тестовые данные' AND created_by = 'migration';
